#include <stdio.h>

#define N 2

int main() {
    int a[N][N] = {{1, 2}, {3, 4}};
    int b[N][N] = {{2, 0}, {1, 2}};
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int sum = 0;
            for (int k = 0; k < N; k++) {
                sum += a[i][k] * b[k][j];
            }
            printf("%d ", sum);
        }
        printf("\n");
    }
    return 0;
}
